import { useNavigate } from 'react-router-dom';
import { BoxMeter } from '@/components/ui/BoxMeter.js';
import { Button } from '@/components/ui/Button.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { accuracy as percentOf, totals } from '@lexpad/core';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useCurrentDay } from '@/lib/useCurrentDay.js';
import { CHART_DAYS, loadProgress, type ProgressData } from './data.js';
import styles from './Progress.module.css';

const LOADING: ProgressData = {
  started: 0,
  totalWords: 0,
  mastered: 0,
  boxes: [0, 0, 0, 0, 0],
  accuracyByCategory: [],
  streak: { current: 0, longest: 0 },
  streakActive: false,
  history: [],
  today: 0,
  hasNotebook: true,
};

const BOX_CLASS = [styles.box1, styles.box2, styles.box3, styles.box4, styles.box5];

/**
 * Progress: four headline numbers, the Leitner ladder, a fortnight of
 * activity and accuracy per topic. Every number comes from the local
 * database, so it is right offline and the same after a sync.
 */
export function Progress(): React.JSX.Element {
  const navigate = useNavigate();
  const now = useCurrentDay();
  const data = useLiveQuery(() => loadProgress(now), LOADING, [now]);
  const window = totals(data.history);
  const busiest = Math.max(...data.history.map((day) => day.reviewed), 1);
  const fullest = Math.max(...data.boxes, 1);
  const reviewed = data.accuracyByCategory.reduce((sum, row) => sum + row.reviewed, 0);
  const correct = data.accuracyByCategory.reduce((sum, row) => sum + row.correct, 0);

  if (!data.hasNotebook || data.totalWords === 0) {
    return (
      <main className={styles.screen}>
        <div className={styles.head}>
          <h1 className={styles.title}>{t('progress.title')}</h1>
          <p className={styles.lead}>{t('progress.lead')}</p>
        </div>
        {/* Five empty boxes, which is what this screen is about: nothing is
            claimed to have happened, and the shape of what will appear is
            visible before it does. */}
        <EmptyState
          mark={
            /* The five boxes, empty: the shape of what will appear is more
               use here than a symbol standing in for it. Nothing is
               claimed to have happened. */
            <span className={styles.waitingLadder} aria-hidden="true">
              {[0, 1, 2, 3, 4].map((step) => (
                <span key={step} className={styles.waitingStep} />
              ))}
            </span>
          }
          title={t('progress.waitingTitle')}
          body={t('progress.noWords')}
          actions={
            <Button
              onClick={() => {
                void navigate(data.hasNotebook ? '/notebook?add=1' : '/welcome');
              }}
            >
              {t('add.title')}
            </Button>
          }
        />
      </main>
    );
  }

  return (
    <main className={styles.screen}>
      <div className={styles.head}>
        <h1 className={styles.title}>{t('progress.title')}</h1>
        <p className={styles.lead}>{t('progress.lead')}</p>
      </div>

      {/* Three across: the numbers that describe the account rather than
          the notebook. How many words have been started belongs with the
          boxes underneath, because it is the total those boxes add up to. */}
      <div className={styles.tiles}>
        <Tile
          value={String(data.streakActive ? data.streak.current : 0)}
          label={t('progress.streak')}
          tone={styles.tileGold}
        />
        <Tile value={String(data.mastered)} label={t('progress.mastered')} tone={styles.tileAccent} />
        <Tile
          value={reviewed === 0 ? '—' : `${String(percentOf(reviewed, correct))}%`}
          label={t('progress.accuracy')}
          tone={styles.tileTeal}
        />
      </div>

      <section className={styles.section}>
        <div className={styles.sectionHead}>
          <h2 className={styles.sectionTitle}>{t('progress.boxes')}</h2>
          <p className={styles.sectionNote}>{t('progress.boxesNote')}</p>
        </div>
        <p className={styles.startedLine}>
          <span className={styles.startedNumber}>{data.started}</span>
          <span className={styles.startedLabel}>{t('progress.started')}</span>
        </p>
        <div className={styles.panel}>
          {data.boxes.map((count, index) => (
            <div key={index} className={styles.boxRow}>
              {/* The same five rising bars a word carries on its own row and
                  in a session. Seeing them here next to "Box 1" through
                  "Box 5" is where the shape gets learnt, without a legend. */}
              <BoxMeter box={index + 1} className={styles.boxMark} />
              <span className={styles.boxName}>{t('progress.box', { n: index + 1 })}</span>
              <span className={styles.boxTrack}>
                <span
                  className={cx(styles.boxFill, BOX_CLASS[index])}
                  style={{ width: `${String(Math.round((count / fullest) * 100))}%` }}
                />
              </span>
              <span className={styles.boxCount}>{count}</span>
            </div>
          ))}
        </div>
      </section>

      <section className={styles.section}>
        <div className={styles.sectionHead}>
          <h2 className={styles.sectionTitle}>{t('progress.activity')}</h2>
          <span className={styles.sectionNote}>
            {t('progress.activityTotal', { count: window.reviewed })}
          </span>
        </div>
        <div className={styles.panel}>
          <div className={styles.chart}>
            {data.history.slice(-CHART_DAYS).map((day) => (
              <span key={day.day} className={styles.day}>
                <span
                  className={cx(
                    styles.bar,
                    day.reviewed > 0 && styles.barOn,
                    day.reviewed > 0 && day.day === data.today && styles.barToday,
                  )}
                  style={{
                    height: `${String(
                      Math.max(Math.round((day.reviewed / busiest) * 100), day.reviewed > 0 ? 5 : 1.5),
                    )}%`,
                  }}
                  role="img"
                  aria-label={t('progress.topicLabel', {
                    percent: percentOf(day.reviewed, day.correct),
                    reviewed: day.reviewed,
                  })}
                />
                <span className={styles.dayLabel}>{new Date(day.day * 86_400_000).getUTCDate()}</span>
              </span>
            ))}
          </div>
        </div>
      </section>

      <section className={styles.section}>
        <h2 className={styles.sectionTitle}>{t('progress.byCategory')}</h2>
        <div className={styles.topics}>
          {data.accuracyByCategory.length === 0 ? (
            <EmptyState
              compact
              icon="grid"
              tone="quiet"
              title={t('progress.noTopicsTitle')}
              body={t('progress.noTopics')}
            />
          ) : (
            data.accuracyByCategory.map((row) => {
              const percent = percentOf(row.reviewed, row.correct);
              return (
                <div key={row.category} className={styles.topic}>
                  <span className={styles.topicName}>{row.category.replace(/-/g, ' ')}</span>
                  <span className={styles.topicTrack}>
                    <span
                      className={cx(styles.topicFill, toneFor(percent))}
                      style={{ width: `${String(percent)}%` }}
                    />
                  </span>
                  <span className={styles.topicLabel}>
                    {t('progress.topicLabel', { percent, reviewed: row.reviewed })}
                  </span>
                </div>
              );
            })
          )}
        </div>
      </section>
    </main>
  );
}

function Tile({
  value,
  label,
  tone,
}: {
  value: string;
  label: string;
  tone?: string | undefined;
}): React.JSX.Element {
  return (
    <div className={cx(styles.tile, tone)}>
      <span className={styles.tileValue} role="img" aria-label={label}>
        {value}
      </span>
      <span className={styles.tileLabel}>{label}</span>
    </div>
  );
}

/** The prototype's three accuracy bands. */
function toneFor(percent: number): string | undefined {
  if (percent >= 80) return styles.good;
  if (percent >= 55) return styles.fair;
  return styles.poor;
}
